{
  "name": "wasmtime-github-release",
  "version": "0.0.0",
  "main": "main.js",
  "dependencies": {
    "@actions/core": "^1.6",
    "@actions/github": "^5.0",
    "glob": "^7.1.5"
  }
}

const core = require('@actions/core');
const path = require("path");
const fs = require("fs");
const github = require('@actions/github');
const glob = require('glob');

function sleep(milliseconds) {
  return new Promise(resolve => setTimeout(resolve, milliseconds));
}

async function runOnce() {
  // Load all our inputs and env vars. Note that `getInput` reads from `INPUT_*`
  const files = core.getInput('files');
  const name = core.getInput('name');
  const token = [REDACTED]'token');
  const slug = process.env.GITHUB_REPOSITORY;
  const owner = slug.split('/')[0];
  const repo = slug.split('/')[1];
  const sha = process.env.HEAD_SHA;

  core.info(`files: ${files}`);
  core.info(`name: ${name}`);

  const options = {
    request: {
      timeout: 30000,
    }
  };
  const octokit = github.getOctokit(token, options);

  // Delete the previous release since we can't overwrite one. This may happen
  // due to retrying an upload or it may happen because we're doing the dev
  // release.
  const releases = await octokit.paginate("GET /repos/:owner/:repo/releases", { owner, repo });
  for (const release of releases) {
    if (release.tag_name !== name) {
      continue;
    }
    const release_id = release.id;
    core.info(`deleting release ${release_id}`);
    await octokit.rest.repos.deleteRelease({ owner, repo, release_id });
  }

  // We also need to update the `dev` tag while we're at it on the `dev` branch.
  if (name == 'nightly') {
    try {
      core.info(`updating nightly tag`);
      await octokit.rest.git.updateRef({
        owner,
        repo,
        ref: 'tags/nightly',
        sha,
        force: true,
      });
    } catch (e) {
      core.error(e);
      core.info(`creating nightly tag`);
      await octokit.rest.git.createTag({
        owner,
        repo,
        tag: 'nightly',
        message: 'nightly release',
        object: sha,
        type: 'commit',
      });
    }
  }

  // Creates an official GitHub release for this `tag`, and if this is `dev`
  // then we know that from the previous block this should be a fresh release.
  core.info(`creating a release`);
  const release = await octokit.rest.repos.createRelease({
    owner,
    repo,
    name,
    tag_name: name,
    target_commitish: sha,
    prerelease: name === 'nightly',
  });
  const release_id = release.data.id;

  // Upload all the relevant assets for this release as just general blobs.
  for (const file of glob.sync(files)) {
    const size = fs.statSync(file).size;
    const name = path.basename(file);

    await runWithRetry(async function() {
      // We can't overwrite assets, so remove existing ones from a previous try.
      let assets = await octokit.rest.repos.listReleaseAssets({
        owner,
        repo,
        release_id
      });
      for (const asset of assets.data) {
        if (asset.name === name) {
          core.info(`delete asset ${name}`);
          const asset_id = asset.id;
          await octokit.rest.repos.deleteReleaseAsset({ owner, repo, asset_id });
        }
      }

      core.info(`upload ${file}`);
      const headers = { 'content-length': size, 'content-type': 'application/octet-stream' };
      const data = fs.createReadStream(file);
      await octokit.rest.repos.uploadReleaseAsset({
        data,
        headers,
        name,
        url: release.data.upload_url,
      });
    });
  }
}

async function runWithRetry(f) {
  const retries = 10;
  const maxDelay = 4000;
  let delay = 1000;

  for (let i = 0; i < retries; i++) {
    try {
      await f();
      break;
    } catch (e) {
      if (i === retries - 1)
        throw e;

      core.error(e);
      const currentDelay = Math.round(Math.random() * delay);
      core.info(`sleeping ${currentDelay} ms`);
      await sleep(currentDelay);
      delay = Math.min(delay * 2, maxDelay);
    }
  }
}

async function run() {
  await runWithRetry(runOnce);
}

run().catch(err => {
  core.error(err);
  core.setFailed(err.message);
});

use std::{fmt::Display, path::PathBuf};

use lsp_types::TextDocumentPositionParams;
use serde::{Deserialize, Deserializer, Serialize};
use serde_json::{Map, Value};
use uuid::Uuid;

const HF_INFERENCE_API_HOSTNAME: &str = "api-inference.huggingface.co";

#[derive(Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AcceptCompletionParams {
    pub request_id: Uuid,
    pub accepted_completion: u32,
    pub shown_completions: Vec<u32>,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RejectCompletionParams {
    pub request_id: Uuid,
    pub shown_completions: Vec<u32>,
}

#[derive(Clone, Copy, Debug, Default, Deserialize, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Ide {
    Neovim,
    VSCode,
    JetBrains,
    Emacs,
    Jupyter,
    Sublime,
    VisualStudio,
    #[default]
    Unknown,
}

impl Display for Ide {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.serialize(f)
    }
}

fn parse_ide<'de, D>(d: D) -> std::result::Result<Ide, D::Error>
where
    D: Deserializer<'de>,
{
    Option::deserialize(d).map(|b| b.unwrap_or_default())
}

fn parse_url<'de, D>(d: D) -> std::result::Result<String, D::Error>
where
    D: Deserializer<'de>,
{
    Option::deserialize(d).map(|b| b.unwrap_or_else(hf_default_url))
}

fn hf_default_url() -> String {
    format!("https://{HF_INFERENCE_API_HOSTNAME}")
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "lowercase", tag = "backend")]
pub enum Backend {
    HuggingFace {
        #[serde(default = "hf_default_url", deserialize_with = "parse_url")]
        url: String,
    },
    LlamaCpp {
        url: String,
    },
    Ollama {
        url: String,
    },
    OpenAi {
        url: String,
    },
    Tgi {
        url: String,
    },
}

impl Default for Backend {
    fn default() -> Self {
        Self::HuggingFace {
            url: hf_default_url(),
        }
    }
}

impl Backend {
    pub fn is_using_inference_api(&self) -> bool {
        match self {
            Self::HuggingFace { url } => url.contains(HF_INFERENCE_API_HOSTNAME),
            _ => false,
        }
    }

    pub fn url(self) -> String {
        match self {
            Self::HuggingFace { url } => url,
            Self::LlamaCpp { url } => url,
            Self::Ollama { url } => url,
            Self::OpenAi { url } => url,
            Self::Tgi { url } => url,
        }
    }
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct FimParams {
    pub enabled: bool,
    pub prefix: String,
    pub middle: String,
    pub suffix: String,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(untagged)]
pub enum TokenizerConfig {
    Local {
        path: PathBuf,
    },
    HuggingFace {
        repository: String,
        api_token: [REDACTED],
    },
    Download {
        url: String,
        to: PathBuf,
    },
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GetCompletionsParams {
    #[serde(flatten)]
    pub text_document_position: TextDocumentPositionParams,
    #[serde(default)]
    #[serde(deserialize_with = "parse_ide")]
    pub ide: Ide,
    pub fim: FimParams,
    pub api_token: [REDACTED],
    pub model: String,
    #[serde(flatten)]
    pub backend: Backend,
    pub tokens_to_clear: Vec<String>,
    pub tokenizer_config: Option<TokenizerConfig>,
    pub context_window: usize,
    pub tls_skip_verify_insecure: bool,
    #[serde(default)]
    pub request_body: Map<String, Value>,
    #[serde(default)]
    pub disable_url_path_completion: bool,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Completion {
    pub generated_text: String,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct GetCompletionsResult {
    pub request_id: Uuid,
    pub completions: Vec<Completion>,
}
